{"code":"def transform(grid):
    g=[r[:] for r in grid]
    H=len(g); W=len(g[0])
    # instruction groups are contiguous nonzero runs on first and last rows
    groups=[]
    for rr in {0,H-1}:
        c=0
        while c<W:
            if g[rr][c]!=0:
                s=c
                while c<W and g[rr][c]!=0: c+=1
                groups.append((g[rr][s:c],rr,s))
            else: c+=1
    # each isolated non-boundary colored cell is an anchor
    for r in range(1,H-1):
        for c in range(W):
            v=g[r][c]
            if v==0: continue
            src=None
            for seq,_,_ in groups:
                if v in seq:
                    src=(seq,seq.index(v)); break
            if src:
                seq,k=src
                start=c-k
                for j,x in enumerate(seq):
                    cc=start+j
                    if 0<=cc<W: g[r][cc]=x
    return g"}

